"""Transport, destinations and polite travel questions."""
from english.u18.content import CORE, MEANINGS, PLACES, picture
from english.study.author import word as w, question as q, choice as c, dialogue as d
from english.study.render import render_study as render

def data():
    words = [w('transport', k, v, e, image=im) for k, v, e, im in [('bus', 'xe buýt', 'You can get there by bus.', 'by bus'), ('bicycle', 'xe đạp', 'You can get there by bicycle.', 'by bicycle'), ('taxi', 'taxi', 'You can get there by taxi.', 'by taxi'), ('on foot', 'đi bộ', 'You can get there on foot.', 'on foot')]]
    words += [w('transport', k, v, e) for k, v, e in [('train', 'tàu hỏa', 'We can go by train.'), ('boat', 'thuyền', 'Can I get there by boat?'), ('ferry', 'phà', 'We can go to the island by ferry.'), ('bus stop', 'điểm dừng xe buýt', 'The bus stop is over there.')]]
    words += [w('places', k, v, 'I want to visit ' + k + '.') for k, v in zip(PLACES, ['Nhà hát Lớn Hà Nội', 'Cầu Rồng', 'Quảng trường Ngọ Môn', 'Bảo tàng Thành phố Hồ Chí Minh'])]
    words += [w('places', k, v, 'I want to visit the ' + k + '.') for k, v in [('pagoda', 'chùa'), ('water park', 'công viên nước'), ('aquarium', 'thủy cung'), ('island', 'đảo')]]
    words += [w('trip', k, v, e) for k, v, e in [('visit', 'tham quan', 'Where do you want to visit?'), ('get to', 'đến', 'How can I get to the museum?'), ('far', 'xa', 'Is it far from here?'), ('lost', 'bị lạc', 'Excuse me! I am lost.')]]
    dialogs = [d('transport', 'Chọn phương tiện', 'How can I get there?', 'You can get there by bus.', 'By + phương tiện; không thêm a.'), d('transport', 'Đi bộ', 'How can I get to the museum?', 'You can get there on foot.', 'On foot, không by foot.'), d('places', 'Nơi muốn đến', 'Where do you want to visit?', 'I want to visit Ha Noi Opera House.', 'Want to + visit; không thêm to sau visit.'), d('places', 'Cầu Rồng', 'Where do you want to visit?', 'I want to visit Dragon Bridge.', 'Tên địa danh có chữ và audio, không đoán từ một bức tranh chung.'), d('trip', 'Hỏi thật lịch sự', 'Excuse me! How can I get to the aquarium?', 'You can get there by bus.', 'Can + get, không gets/to get.'), d('trip', 'Ngữ điệu câu hỏi', 'Is it far from here?', 'No, it is not. We can walk there.', 'Câu hỏi Yes/No thường lên giọng; thông tin theo thẻ giả định, không phải hướng dẫn đường thật.')]
    exercises = [c('transport-listen', 'transport', 'Which transport phrase is heard?', 'by taxi', 'Nghe by taxi.', CORE, speech='You can get there by taxi.'), q('transport-on', 'transport', 'You can get there ___ foot.', 'on', 'On foot.'), q('transport-by', 'transport', 'You can get there ___ bus.', 'by', 'By bus.'), q('transport-bicycle', 'transport', 'Complete: bi___. Write the whole vehicle word.', 'bicycle', 'Bicycle.'), c('place-listen', 'places', 'Which destination is named?', PLACES[1], 'Nghe Dragon Bridge.', PLACES, speech='I want to visit Dragon Bridge.'), q('place-to', 'places', 'I want ___ visit Ha Noi Opera House.', 'to', 'Want to visit.'), q('place-visit', 'places', 'Where do you want to ___?', 'visit', 'Want to + visit.'), q('place-sentence', 'places', 'Card: I / want to visit / Ngo Mon Square. Write one sentence in this order.', 'I want to visit Ngo Mon Square.', 'Visit + nơi đến, không visit to.'), c('trip-listen', 'trip', 'Which transport phrase takes the group to the island?', 'by boat', 'Nghe chặng tới đảo.', CORE + ['by boat'], speech='First, we visit the museum by bus. Then, we go to the island by boat.'), q('trip-base', 'trip', 'How can I ___ there? Use get.', 'get', 'Can + get, không gets.'), q('trip-full', 'trip', 'Rewrite in full: I can’t get there by bus.', 'I cannot get there by bus.', 'Can’t = cannot.'), q('trip-sentence', 'trip', 'Card: get there / on foot. Write an answer starting with You can.', 'You can get there on foot.', 'Can + get; on foot.')]
    return dict(unit=18, key='mia5:learn:en-u18-v1', intro='Học nơi muốn đến, cách hỏi đường lịch sự và phương tiện: nghe, nghe chậm, ABC và hội thoại.', groups=[dict(id='transport', name='Phương tiện đi lại', tip='By bus/bicycle/taxi/train/boat/ferry; on foot là đi bộ. Không dùng by foot hoặc by a bus.'), dict(id='places', name='Em muốn tham quan đâu?', tip='Where do you want to visit? I want to visit… Tên địa danh trong sách được học bằng chữ và audio. Visit + nơi đến, không thêm to sau visit.'), dict(id='trip', name='Hỏi đường và đọc kế hoạch', tip='How can I get to…? You can get there… Can + nguyên mẫu get. Câu hỏi Yes/No như Is it far from here? thường lên giọng. Lộ trình trong đề là giả định; đọc đúng người và chặng. ABC là tên chữ cái, không phải phonics.')], words=words, dialogues=dialogs, exercises=exercises)

def render_study():
    return render(data(), picture)
